  unique_per_match = excluded.unique_per_match,
  show_in_summary = excluded.show_in_summary,
  hint = excluded.hint,
  sort_order = excluded.sort_order;

-- Retira los campos que ya no existen en la definición TypeScript.
-- Las partidas antiguas conservan su jsonb intacto: solo dejan de mostrarse.
delete from public.game_score_fields f
where f.game_slug in ('monopoly', 'trivial-pursuit', 'scrabble', 'uno', 'rummikub', 'domino', 'parchis', 'catan', 'carcassonne', 'camel-up', 'aventureros-al-tren', 'azul', 'splendor', 'king-of-tokyo', 'dixit', 'patchwork', '7-wonders', '7-wonders-duel', 'wingspan', 'cascadia', 'everdell', 'dominion', 'terraforming-mars')
  and not exists (
    select 1 from (values
      ('monopoly', 'net_worth'),
      ('monopoly', 'properties'),
